<script module lang="ts">
/**
 * Large title block that opens a page (`design/components/hero.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/hero.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/hero.module.css'
import Inline from '../layout/Inline.svelte'

export type HeroAlign = NonNullable<HeroProps['align']>

export interface HeroProps {
  /**
   * Buttons; the page's primary action goes here when a Hero opens the page.
   */
  actions?: Snippet
  align?: 'start' | 'center'
  lede?: string
  title: string
}
</script>

<script lang="ts">
let { actions, align = 'start', lede, title }: HeroProps = $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get actions() {
    return actions
  },
}
</script>

{@render joined.start?.()
}{#if joined.shown
  }<section class={styles.hero} data-align={align} data-member="hero"
    ><h1 class={styles.title}>{title}</h1
    >{#if lede !== undefined}<p class={styles.lede}>{lede}</p>{/if
    }{#if slots.actions
      }<Inline gap={3} wrap={true} justify={align === 'center' ? 'center' : 'start'}
        >{@render actions?.()
      }</Inline
    >{/if
  }</section
>{/if
}{@render joined.end?.()}
